import numpy as np
import pandas as pd
from sklearn.base import BaseEstimator, RegressorMixin
from sklearn.model_selection import cross_val_score

# готово, как в теории: Xc (столбец courier), y (минуты)

class CourierMean(RegressorMixin, BaseEstimator):
    def fit(self,X,y):
        self.means_=X.assign(target=np.asarray(y)).groupby("courier")["target"].mean()
        self.global_=np.mean(y)
        return self
    def predict(self,X):
        return X["courier"].map(self.means_).fillna(self.global_).to_numpy()

def cv(m,X,y):
    return -cross_val_score(m,X,y,cv=5,scoring="neg_mean_absolute_error")
